-- Generated by tools/build_postgres_tombstone_triggers.py
-- Ports 18 SQLite AFTER DELETE tombstone triggers.
-- Review POSTGRES_TOMBSTONE_TRIGGERS.md before applying.

CREATE OR REPLACE FUNCTION app_record_sync_tombstone()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    v_school_id integer;
    v_deleted_at text := to_char(date_trunc('second', clock_timestamp() AT TIME ZONE 'UTC'),
                                'YYYY-MM-DD"T"HH24:MI:SS');
BEGIN
    IF OLD.client_uuid IS NULL THEN
        RETURN OLD;
    END IF;

    CASE TG_TABLE_NAME
        WHEN 'attendance_records' THEN
            SELECT school_id FROM classes WHERE id = OLD.class_id INTO v_school_id;
        WHEN 'class_subjects' THEN
            SELECT school_id FROM classes WHERE id = OLD.class_id INTO v_school_id;
        WHEN 'classes' THEN
            v_school_id := OLD.school_id;
        WHEN 'enrollments' THEN
            SELECT school_id FROM classes WHERE id = OLD.class_id INTO v_school_id;
        WHEN 'grade_scale' THEN
            v_school_id := OLD.school_id;
        WHEN 'grading_config' THEN
            v_school_id := OLD.school_id;
        WHEN 'materials' THEN
            v_school_id := OLD.school_id;
        WHEN 'scores' THEN
            SELECT c.school_id FROM students s JOIN classes c ON c.id = s.class_id WHERE s.id = OLD.student_id INTO v_school_id;
        WHEN 'sessions' THEN
            v_school_id := OLD.school_id;
        WHEN 'staff_attendance' THEN
            v_school_id := OLD.school_id;
        WHEN 'student_skill_ratings' THEN
            SELECT c.school_id FROM students s JOIN classes c ON c.id = s.class_id WHERE s.id = OLD.student_id INTO v_school_id;
        WHEN 'student_term_info' THEN
            SELECT c.school_id FROM students s JOIN classes c ON c.id = s.class_id WHERE s.id = OLD.student_id INTO v_school_id;
        WHEN 'students' THEN
            SELECT school_id FROM classes WHERE id = OLD.class_id INTO v_school_id;
        WHEN 'subjects' THEN
            v_school_id := OLD.school_id;
        WHEN 'terms' THEN
            SELECT school_id FROM sessions WHERE id = OLD.session_id INTO v_school_id;
        WHEN 'timetable_entries' THEN
            v_school_id := OLD.school_id;
        WHEN 'timetable_periods' THEN
            v_school_id := OLD.school_id;
        WHEN 'users' THEN
            v_school_id := OLD.school_id;
        ELSE
            RAISE EXCEPTION 'No tombstone school-scope mapping for table %', TG_TABLE_NAME
                USING ERRCODE = '22023';
    END CASE;

    INSERT INTO sync_tombstones (school_id, entity, client_uuid, deleted_at)
    VALUES (v_school_id, TG_TABLE_NAME, OLD.client_uuid, v_deleted_at);
    RETURN OLD;
END;
$$;

DROP TRIGGER IF EXISTS trg_attendance_records_tombstone ON attendance_records;
CREATE TRIGGER trg_attendance_records_tombstone
AFTER DELETE ON attendance_records
FOR EACH ROW
WHEN (OLD.client_uuid IS NOT NULL)
EXECUTE FUNCTION app_record_sync_tombstone();

